sys_ux_client_script.script:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
function handler({
    api,
    event,
    helpers,
    imports
}) {
    console.debug(">>> Add Detail data()", api, event);
debugger;
    // Deep Copyする
    var records = structuredClone(api.state.records);

    // 空明細のDeep Copy
    const blankDetail = structuredClone(api.state.blankDetail);
    blankDetail.bulk_personnel.value = api.state.tableSysId;

    // エラー設定
    blankDetail.issue_date.invalid = true;
    if (blankDetail.departmentArray[0]) {
        blankDetail.departmentArray[0].dept.invalid = true;
        blankDetail.departmentArray[0].position.invalid = true;
    }
    blankDetail.location.invalid = true;

    // チェックマークの位置。未選択の場合は、-1
    const pos = records.findIndex(rec=> rec && rec.checked === true);
    console.debug(">>>>> Checked Position: ", pos);
    console.warn(pos);

    if (pos < 0) {
        // 未選択：末尾に追加
        // 空白データを追加
        const nextIndex = records.length;
        blankDetail.order.value = nextIndex;
        blankDetail.order.displayValue = nextIndex;

        records.push(blankDetail);
    } else {
        // 選択あり：直前に追加

        // チェックを外す
        records[pos].checked = false;

        // その場に挿入
        records.splice(pos, 0, blankDetail);
    }


    api.setState("records", records);

}
